// src/utils/parseToGraph.js
export function parseToGraph(code) {
  const lines = code
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#'));

  const nodes = [];
  const edges = [];

  let prevId = null;
  let stack = [];

  lines.forEach((line, i) => {
    const id = `node-${i}`;
    const label = line;

    // Detect conditional or loop structures
    if (line.startsWith('if')) {
      nodes.push({ id, label: `🔹 ${label}`, type: 'decision' });
      stack.push(id);
    } else if (line.startsWith('elif') || line.startsWith('else')) {
      nodes.push({ id, label: `🔸 ${label}`, type: 'branch' });
      const lastIf = stack[stack.length - 1];
      if (lastIf) edges.push({ source: lastIf, target: id });
    } else if (line.startsWith('for') || line.startsWith('while')) {
      nodes.push({ id, label: `🔁 ${label}`, type: 'loop' });
      stack.push(id);
    } else if (line.startsWith('def')) {
      nodes.push({ id, label: `⚙️ ${label}`, type: 'function' });
    } else if (line.startsWith('return')) {
      nodes.push({ id, label: `🏁 ${label}`, type: 'end' });
    } else {
      nodes.push({ id, label, type: 'process' });
    }

    // Connect to previous line if not a branch start
    if (prevId && !line.startsWith('elif') && !line.startsWith('else')) {
      edges.push({ source: prevId, target: id });
    }

    prevId = id;
  });

  return { nodes, edges };
}

export const codeTemplates = {
