`,
  javascript: `function checkEvenOdd(num) {
  if (num % 2 === 0) {
    console.log("Even");
  } else {
    console.log("Odd");
  }
}

for (let i = 0; i < 5; i++) {
  checkEvenOdd(i);
}`
};
